{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Kernen stemmer med rubrikken og kilderne: ret til SU eller slutlån, tillægget sammen med SU-stipendium eller slutlån, videregående uddannelse eller dansk EUD, og varig funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde. Ingen af rubrikkens væsentlige fejl er begået. Diagnose alene er ikke gjort tilstrækkelig, EUD er med, og tillægget er ikke gjort selvstændigt. Svaret har ekstra påstande, men de er ikke i modstrid med rubrikken, og de behandles under C06 og C07."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: de almindelige SU-betingelser og at tillægget gives sammen med SU-stipendium eller slutlån, videregående uddannelse eller EUD, og varig funktionsnedsættelse med meget betydelige begrænsninger. De understøttende elementer (EUX og erhvervslignende uddannelse i udlandet) mangler, men de er ikke kritiske."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvad betingelserne er, og giver både et kort svar og en struktureret gennemgang."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver identificerbare kilder: Vejledning nr. 10157 af 5. oktober 2026, SU-bekendtgørelsen nr. 841 af 2026 og Ankenævnets afgørelser. De væsentlige udsagn er knyttet til dem via henvisningsnumre og kildelisten. Numrene kan dog ikke altid kobles præcist til de enkelte kilder."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledningen fra 2026 og SU-bekendtgørelsen fra 2026 er gyldige og autoritative. Flere af udsagnene hviler imidlertid på Ankenævnets afgørelser og KEN-dokumenter fra 2013-2014. De ligger uden for de frosne aktuelle kilder, og det er ikke vist, at de er aktuelle. Kildegrundlaget er derfor delvist ikke aktuelt inden for kildeafgrænsningen."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de frosne passager. Svaret hævder, at vejledningen opregner fire hovedkrav inklusive 'særlige krav til visse ikke-danske statsborgere', mens afsnit 3.1 kun nævner tre. Svaret siger også, at SU skal være modtaget i udbetalingsperioden, at tærsklen er 'stort set ikke muligt at påtage sig arbejde i nævneværdigt omfang', at vurderingen tager udgangspunkt i typiske studenterjobs og ikke i studierelevans eller geografi, at flere funktionsnedsættelser vurderes samlet, og at man kan søge igen ved væsentlig ændring. Ingen af disse er understøttet af de udleverede passager."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer regler og tærskler uden støtte i review-materialet: et nationalitetskrav som fjerde hovedkrav, 'typiske studenterjobs', at studierelevans og geografi er udelukket, en samlet vurdering af flere funktionsnedsættelser, en 'stort set ikke muligt'-formulering og muligheden for at søge igen."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Den krævede kvalifikation er, at svaret er et overblik, og at de almindelige SU-betingelser ikke er udtømmende gengivet. Rubrikken kræver ikke en særskilt standardadvarsel. Svaret bevarer 'varig', 'meget betydelige' og 'normalt ikke nok'. Det henviser desuden til de almindelige SU-betingelser, og det skal kontrolleres, om man opfylder dem i den relevante periode."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinnene er indbyrdes sammenhængende, og konklusionen følger af dem: uddannelsesmæssig berettigelse plus varig funktionsnedsættelse med meget betydelige begrænsninger. Der er kun en mindre inkonsistens mellem tre betingelser i det korte svar og fire hovedkrav i uddybningen."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Modaliteterne gengiver generelt kilderne: 'skal', 'kan kun tildele' og 'er en betingelse'. 'Normalt ikke nok' bevarer et skøn. De hårde formuleringer om studenterjobs og geografi er et problem for kildestøtten, ikke for modaliteten."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "yes",
      "reason": "Svaret kræver ret til og modtagelse af SU eller slutlån og forklarer, at tillægget gives sammen med SU-stipendium eller slutlån."
    },
    "A2": {
      "label": "yes",
      "reason": "Svaret kræver indskrivning på og gennemførelse af en videregående uddannelse eller dansk EUD."
    },
    "A3": {
      "label": "yes",
      "reason": "Svaret kræver en varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde."
    },
    "A4": {
      "label": "partial",
      "reason": "Svaret nævner ret til SU og de almindelige SU-betingelser. Det gengiver ikke eksplicit, at man skal være indskrevet på og gennemgå en SU-berettigende uddannelse."
    },
    "A6": {
      "label": "partial",
      "reason": "Dansk EUD er nævnt, men ikke at EUD omfatter EUX. Svaret nævner heller ikke, at erhvervslignende uddannelser i udlandet ikke er omfattet."
    }
  },
  "overall_notes": "Svaret rammer de tre kritiske betingelser korrekt og dækker spørgsmålet. Det svækkes af flere påstande, især nationalitetskravet som fjerde hovedkrav i vejledningen, de strenge tærskel- og studenterjob-udsagn og samlet vurdering, som ikke er understøttet af de frosne passager. Svaret hviler delvist på ældre Ankenævns-afgørelser uden for den aktuelle kildeafgrænsning. Det udelader EUX og afgrænsningen af udenlandsk erhvervslignende uddannelse, men det er kun understøttende elementer."
}

